  def self.fetch(key) = FOODS.find { |f| f.key == key } || raise(KeyError, key)
  def self.featured = FOODS.select(&:featured).sort_by { |f| -f.protein_g }
  def self.categories = FOODS.map(&:category).uniq

  def self.search(query)
    q = query.to_s.downcase.strip
    return featured if q.empty?
    FOODS.select { |f| f.name.downcase.include?(q) || f.category.downcase.include?(q) }.sort_by { |f| -f.protein_g }
  end
end
